"""Page presenters; data and action helpers supplied by the runtime."""
from __future__ import annotations
from .. import gstudio_workbench as runtime

def _render_archive_legacy_v1(
    token: str, notice: str = "", error: str = "", *, view: str = "",
    publish_records: list[dict[str, object]] | None = None,
) -> str:
    selected_view = "archive" if view == "archive" else "publish"
    message = runtime.flash_message(notice, error)
    primary_tabs = (
        '<nav class="archive-primary-tabs" role="tablist" aria-label="发布与资料归档视图">'
        f'<a class="archive-primary-tab{" active" if selected_view == "publish" else ""}" role="tab" aria-selected="{str(selected_view == "publish").lower()}" href="/archive">发布管理</a>'
        f'<a class="archive-primary-tab{" active" if selected_view == "archive" else ""}" role="tab" aria-selected="{str(selected_view == "archive").lower()}" href="/archive?view=archive">资料归档</a></nav>'
    )
    primary_style = '<style>.archive-primary-tabs{display:flex;gap:4px;margin:8px 0 10px;padding:4px;border:1px solid var(--line);border-radius:9px;background:var(--line-soft)}.archive-primary-tab{display:flex;flex:1;min-height:34px;align-items:center;justify-content:center;padding:7px 14px;border:0;border-radius:6px;background:transparent;color:var(--muted);font-size:12px;font-weight:750;text-decoration:none}.archive-primary-tab.active{background:var(--surface);color:var(--ink);box-shadow:0 1px 3px rgba(15,23,42,.08)}</style>'
    if selected_view == "publish":
        content = f'<div class="breadcrumb"><a href="/">任务台</a> / 发布归档</div>{message}{primary_tabs}<section class="archive-primary-panel">{runtime.publish_workbench(token, publish_records)}</section>{primary_style}'
        return runtime._layout("发布归档", content, token)

    entries = runtime.workspace_inbox_entries()
    archive_payload = runtime.archive_index.load_index()
    root = runtime.workspace_inbox_root().expanduser()
    drive_root = runtime.external_drive_root()
    entry_map = {str(entry.get("name") or ""): entry for entry in entries if entry.get("fixed")}
    root_items = [entry for entry in entries if not entry.get("fixed")]
    directory_specs = [("root", "根目录", root_items, "")] + [
        (name, name, [], str(entry_map.get(name, {}).get("path") or (root / name)))
        for name in runtime.WORKSPACE_INBOX_FOLDERS
    ]
    tabs: list[str] = []
    panes: list[str] = []
    for index_number, (key, label_text, items, lazy_path) in enumerate(directory_specs):
        safe_key = runtime.quote(key)
        item_count = len(items) if key == "root" else int(entry_map.get(key, {}).get("child_count") or 0)
        tabs.append(f'<button class="inbox-tab{" active" if index_number == 0 else ""}" type="button" data-inbox-tab="{runtime.html.escape(safe_key, quote=True)}"><span>{runtime.html.escape(label_text)}</span><small>{item_count}</small></button>')
        item_rows: list[str] = []
        for item in items:
            is_dir = bool(item.get("is_dir"))
            kind = "文件夹" if is_dir else "文件"
            updated = str(item.get("updated_at") or "")
            item_rows.append(
                f'<div class="inbox-tree-node" data-inbox-search="{runtime.html.escape(str(item.get("name") or "").lower(), quote=True)}"><div class="inbox-item" style="--inbox-depth:0">'
                f'<button class="inbox-expand{" invisible" if not is_dir else ""}" type="button" data-inbox-expand="{runtime.html.escape(str(item.get("path") or ""), quote=True)}" aria-label="展开文件夹" aria-expanded="false">›</button>'
                f'<input type="checkbox" name="inboxSelection" value="{runtime.html.escape(str(item.get("path") or ""), quote=True)}" data-name="{runtime.html.escape(str(item.get("name") or ""), quote=True)}" data-kind="{kind}">'
                f'<span class="inbox-file-copy"><strong>{runtime.html.escape(str(item.get("name") or ""))}</strong><small>{runtime.html.escape(updated) or "—"}</small></span></div><div class="inbox-children" hidden></div></div>'
            )
        empty_text = "根目录当前没有未分类内容。" if key == "root" else "点击标签后按需读取此目录。"
        pane_content = "".join(item_rows) if item_rows else f'<div class="inbox-empty">{empty_text}</div>'
        lazy_attrs = f' data-inbox-pane-path="{runtime.html.escape(lazy_path, quote=True)}" data-loaded="0"' if lazy_path else ' data-loaded="1"'
        panes.append(f'<div class="inbox-pane{" active" if index_number == 0 else ""}" data-inbox-pane="{runtime.html.escape(safe_key, quote=True)}"{lazy_attrs}>{pane_content}</div>')
    drive_rows: list[str] = []
    for item in runtime.directory_entries(drive_root) if drive_root else []:
        is_dir = bool(item.get("is_dir"))
        kind = "文件夹" if is_dir else "文件"
        drive_rows.append(
            f'<div class="inbox-tree-node" data-inbox-search="{runtime.html.escape(str(item.get("name") or "").lower(), quote=True)}"><div class="inbox-item" style="--inbox-depth:0">'
            f'<button class="inbox-expand{" invisible" if not is_dir else ""}" type="button" data-inbox-expand="{runtime.html.escape(str(item.get("path") or ""), quote=True)}" aria-label="展开文件夹" aria-expanded="false">›</button>'
            f'<input type="checkbox" name="inboxSelection" value="{runtime.html.escape(str(item.get("path") or ""), quote=True)}" data-name="{runtime.html.escape(str(item.get("name") or ""), quote=True)}" data-kind="{kind}">'
            f'<span class="inbox-file-copy"><strong>{runtime.html.escape(str(item.get("name") or ""))}</strong><small>{runtime.html.escape(str(item.get("updated_at") or "")) or "—"}</small></span></div><div class="inbox-children" hidden></div></div>'
        )
    configured_executors = runtime.executor_status()
    executor_buttons = runtime.execution_confirm_button("核对归档任务并确认执行", disabled=True)
    inbox_task_specs = [
        ("organize_workspace", "整理整个工作台", "扫描工作台，判断哪些应归档或可删除；先给建议，确认后才移动。"),
        ("archive_selected", "归档选中内容", "自动判断普通资料或发布内容，比较项目目录与历史记录，再进入对应归档流程。"),
    ]
    independent_task_specs = [
        ("organize_archive", "整理当前归档", "整理右侧 NAS 正本所选内容，并协调百度备份副本。"),
        ("organize_baidu", "整理百度历史归档", "只检查百度独有的历史内容，不把它当作当前正本。"),
        ("check_indexes", "检查归档备份", "核验最近 7 天 NAS 正本与百度备份的路径和大小。"),
    ]
    def task_choice_rows(specs: list[tuple[str, str, str]]) -> str:
        return ''.join(f'<label class="archive-task-choice"><input type="radio" name="inbox_action" value="{key}" data-needs-selection="{"1" if key in {"archive_selected", "organize_archive"} else "0"}"><span><strong>{title}</strong><small>{description}</small></span></label>' for key, title, description in specs)
    all_task_specs = inbox_task_specs + independent_task_specs
    prompt_templates = {key: runtime._workspace_inbox_prompt_text(key, "__GSTUDIO_SELECTED_PATH__") for key, _, _ in all_task_specs}
    prompt_json = runtime.json.dumps(prompt_templates, ensure_ascii=False).replace("</", "<\\/")
    form_hidden = f'<input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/archive?view=archive">'
    left_task_form = f'''<form method="post" action="/actions/workspace-inbox-task" id="inboxActionForm" class="archive-inline-tasks" data-execution-confirm data-execution-label="资料整理与归档">{form_hidden}<input type="hidden" id="inboxSourcePath" name="source_path" value=""><span id="inboxTaskHint" hidden></span><div class="archive-inline-task-options">{task_choice_rows(inbox_task_specs)}</div><div class="selection-summary" id="archiveActionSummary"><span>当前动作：<strong>未选择</strong></span><span>选择范围：0 项</span></div><div class="archive-executor-actions">{executor_buttons}</div></form>'''
    right_task_form = f'''<form method="post" action="/actions/workspace-inbox-task" id="archiveMapActionForm" class="archive-inline-tasks" data-execution-confirm data-execution-label="归档区整理与备份核验">{form_hidden}<div class="archive-inline-task-options">{task_choice_rows(independent_task_specs)}</div><div class="selection-summary" id="archiveMapActionSummary"><span>当前动作：<strong>未选择</strong></span><span>选择范围：0 项</span></div><div class="archive-executor-actions">{executor_buttons}</div></form>'''
    def archive_map_node(item: dict[str, object], depth: int = 0) -> str:
        children = item.get("children") or []
        is_dir = item.get("type") == "directory"
        count_text = f"{len(children)} 项" if children else (str(item.get("modified_at") or "") or "—")
        remote_path = str(item.get("remote_path") or "")
        return (
            f'<div class="inbox-tree-node archive-map-node" data-archive-search="{runtime.html.escape(str(item.get("name") or "").lower(), quote=True)}"><div class="inbox-item" style="--inbox-depth:{depth}">'
            f'<button class="inbox-expand{"" if is_dir else " invisible"}" type="button" data-archive-map-expand="{runtime.html.escape(remote_path, quote=True)}" data-loaded="0" aria-expanded="false">›</button>'
            f'<input type="checkbox" name="archiveSelection" value="{runtime.html.escape(remote_path, quote=True)}" data-name="{runtime.html.escape(str(item.get("name") or ""), quote=True)}" data-kind="{"文件夹" if is_dir else "文件"}">'
            f'<span class="inbox-file-copy"><strong>{runtime.html.escape(str(item.get("name") or ""))}</strong><small>{runtime.html.escape(count_text)}</small></span></div>'
            f'<div class="inbox-children" hidden data-archive-children></div></div>'
        )
    archive_tabs: list[str] = []
    archive_panes: list[str] = []
    archive_project_paths: dict[str, str] = {}
    for index_number, project in enumerate(archive_payload.get("projects", []) if isinstance(archive_payload, dict) else []):
        key = str(project.get("gstudio_project") or index_number)
        project_name = str(project.get("name") or key).replace("【项目】", "").removesuffix("Nas")
        project_path = str(project.get("remote_path") or "")
        archive_project_paths[key] = project_path
        archive_tabs.append(f'<button class="inbox-tab{" active" if index_number == 0 else ""}" type="button" data-archive-project-tab="{runtime.html.escape(key, quote=True)}" data-archive-project-path="{runtime.html.escape(project_path, quote=True)}"><span>{runtime.html.escape(project_name)}</span><small>{len(project.get("children") or [])}</small></button>')
        pane_content = ''.join(archive_map_node(child) for child in project.get("children") or []) or '<div class="inbox-empty">当前项目暂无目录。</div>'
        archive_panes.append(f'<div class="inbox-pane{" active" if index_number == 0 else ""}" data-archive-project-pane="{runtime.html.escape(key, quote=True)}">{pane_content}</div>')
    archive_map = ''.join(archive_panes) if archive_panes else '<div class="inbox-empty">NAS 归档索引尚未生成。</div>'
    archive_projects = archive_payload.get("projects", []) if isinstance(archive_payload, dict) else []
    default_archive_project = str(archive_projects[0].get("gstudio_project") or "") if archive_projects else ""
    default_archive_project_path = archive_project_paths.get(default_archive_project) or str(archive_payload.get("remote_root") or runtime.archive_index.archive_root())
    source_switch = '<div class="inbox-source-switch"><button class="active" type="button" data-inbox-source="workspace">工作台</button>' + ('<button type="button" data-inbox-source="drive">移动硬盘</button>' if drive_root else '') + '</div>'
    drive_content = "".join(drive_rows) if drive_rows else '<div class="inbox-empty">移动硬盘根目录为空。</div>'
    drive_browser = f'<div class="inbox-source-pane" data-inbox-source-pane="drive"><div class="inbox-content"><div class="inbox-pane active">{drive_content}</div></div></div>' if drive_root else ''
    archive_head_actions = f'''<div class="inbox-head-actions"><form method="post" action="/actions/refresh-archive"><input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/archive?view=archive"><input type="hidden" id="archiveRefreshProject" name="project" value="{runtime.html.escape(default_archive_project, quote=True)}"><button class="button" type="submit">刷新当前项目</button></form><form method="post" action="/actions/refresh-archive"><input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/archive?view=archive"><button class="button" type="submit">刷新全部</button></form><form method="post" action="/actions/open-archive-path"><input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/archive?view=archive"><button class="button" type="submit">打开 NAS</button></form></div>'''
    content = f"""<div class="breadcrumb"><a href="/">任务台</a> / 发布归档</div>{message}{primary_tabs}
    <section class="archive-primary-panel"><div class="archive-inbox-layout"><section class="panel archive-inbox-browser"><div class="archive-pane-head"><div><strong>收件箱</strong>{source_switch}<small id="inboxRootLabel">{runtime.html.escape(str(root))}</small></div><div class="inbox-head-actions"><form method="post" action="/actions/refresh-workspace-inbox" id="inboxRefresh"><input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/archive?view=archive"><button class="button" type="submit">刷新当前目录</button></form><form method="post" action="/actions/open-workspace-inbox"><input type="hidden" name="csrf" value="{runtime.html.escape(token, quote=True)}"><input type="hidden" name="return_to" value="/archive?view=archive"><input type="hidden" id="inboxOpenPath" name="path" value="{runtime.html.escape(str(root), quote=True)}"><button class="button" type="submit">Finder 打开</button></form></div></div><div class="archive-local-browser"><div class="inbox-source-pane active" data-inbox-source-pane="workspace"><div class="inbox-tabs">{"".join(tabs)}</div><div class="inbox-content">{"".join(panes) if panes else '<div class="inbox-empty">工作台路径不存在或无法读取。</div>'}</div></div>{drive_browser}<div class="inbox-search-row"><input id="inboxSearch" type="search" placeholder="搜索当前目录…" aria-label="搜索当前来源文件"><small id="inboxSelectionLabel">已选 0 项</small><button class="button ghost" id="clearInboxSelection" type="button" disabled>清除选择</button></div></div>{left_task_form}</section><aside class="panel archive-baidu-browser"><div class="archive-pane-head"><div><strong>百度网盘归档区</strong><small id="archiveProjectPath">{runtime.html.escape(default_archive_project_path)}</small></div>{archive_head_actions}</div><div class="inbox-search-row"><input id="archiveSearch" type="search" placeholder="搜索当前项目…" aria-label="搜索当前百度网盘项目"><small id="archiveSelectionLabel">已选 0 项</small><button class="button ghost" id="clearArchiveSelection" type="button" disabled>清除选择</button></div><div class="inbox-tabs archive-project-tabs">{"".join(archive_tabs)}</div><div class="archive-map-scroll">{archive_map}</div>{right_task_form}</aside></div><div class="archive-history">{runtime.history_task_panel('archive','归档记录','archiveHistory')}</div></section>{primary_style}
    <script>const prompts={prompt_json};const source=document.getElementById('inboxSourcePath'),label=document.getElementById('inboxSelectionLabel'),search=document.getElementById('inboxSearch'),taskHint=document.getElementById('inboxTaskHint'),executorButtons=document.querySelectorAll('.archive-executor-actions button'),content=document.querySelector('.inbox-content'),clearSelection=document.getElementById('clearInboxSelection');function makeInboxNode(item,depth){{if(item.load_more){{const more=document.createElement('div');more.className='inbox-empty compact inbox-load-more';more.dataset.inboxLoadMore=item.directory;more.dataset.offset=String(item.offset||0);more.dataset.depth=String(depth);more.textContent='继续下拉加载…';return more}}const node=document.createElement('div');node.className='inbox-tree-node';node.dataset.inboxSearch=(item.name||'').toLowerCase();const row=document.createElement('div');row.className='inbox-item';row.style.setProperty('--inbox-depth',String(depth));const expand=document.createElement('button');expand.type='button';expand.className='inbox-expand'+(item.is_dir?'':' invisible');expand.dataset.inboxExpand=item.path;expand.setAttribute('aria-expanded','false');expand.textContent='›';const radio=document.createElement('input');radio.type='radio';radio.name='inboxSelection';radio.value=item.path;radio.dataset.name=item.name;radio.dataset.kind=item.is_dir?'文件夹':'文件';const copy=document.createElement('span');copy.className='inbox-file-copy';const name=document.createElement('strong');name.textContent=item.name;const time=document.createElement('small');time.textContent=item.updated_at||'—';copy.append(name,time);row.append(expand,radio,copy);const children=document.createElement('div');children.className='inbox-children';children.hidden=true;node.append(row,children);return node}}document.querySelectorAll('[data-inbox-tab]').forEach(tab=>tab.addEventListener('click',()=>{{document.querySelectorAll('[data-inbox-tab]').forEach(item=>item.classList.toggle('active',item===tab));document.querySelectorAll('[data-inbox-pane]').forEach(pane=>pane.classList.toggle('active',pane.dataset.inboxPane===tab.dataset.inboxTab));search.value='';document.querySelectorAll('[data-inbox-search]').forEach(item=>item.style.display='')}}));content.addEventListener('change',event=>{{const input=event.target.closest('[name=inboxSelection]');if(!input)return;source.value=input.value;label.textContent=`已选择：${{input.dataset.kind}} · ${{input.dataset.name}}`;clearSelection.disabled=false}});content.addEventListener('click',async event=>{{const expand=event.target.closest('[data-inbox-expand]');if(expand&&!expand.classList.contains('invisible')){{event.preventDefault();const node=expand.closest('.inbox-tree-node'),children=node.querySelector(':scope > .inbox-children'),opening=children.hidden;children.hidden=!opening;expand.classList.toggle('open',opening);expand.setAttribute('aria-expanded',String(opening));if(opening&&!children.dataset.loaded){{expand.disabled=true;try{{const response=await fetch('/api/workspace-inbox/directory?path='+encodeURIComponent(expand.dataset.inboxExpand),{{headers:{{Accept:'application/json'}}}});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'读取失败');const depth=Number(node.querySelector(':scope > .inbox-item').style.getPropertyValue('--inbox-depth')||0)+1;(payload.children||[]).forEach(item=>children.append(makeInboxNode(item,depth)));if(!(payload.children||[]).length)children.innerHTML='<div class="inbox-empty compact">文件夹为空</div>';children.dataset.loaded='1'}}catch(error){{children.innerHTML='<div class="inbox-empty compact">无法读取此文件夹</div>'}}finally{{expand.disabled=false}}}}return}}const row=event.target.closest('.inbox-item');if(row&&!event.target.matches('input')){{const radio=row.querySelector('[name=inboxSelection]');radio.checked=true;radio.dispatchEvent(new Event('change',{{bubbles:true}}))}}}});clearSelection.addEventListener('click',()=>{{document.querySelectorAll('[name=inboxSelection]').forEach(input=>input.checked=false);source.value='';clearSelection.disabled=true;label.textContent='当前未选资料；全工作台任务不会使用单项选择';const task=document.querySelector('[name=inbox_action]:checked');if(task?.dataset.needsSelection==='1')taskHint.textContent='请先在左侧选择文件或文件夹。'}});document.querySelectorAll('[name=inbox_action]').forEach(input=>input.addEventListener('change',async()=>{{executorButtons.forEach(button=>button.disabled=false);if(input.dataset.needsSelection==='1'&&!source.value){{taskHint.textContent='请先在左侧选择文件或文件夹。';return}}const selected=input.dataset.needsSelection==='1'?source.value:'整个工作台（忽略左侧单项选择）';const prompt=prompts[input.value].replace('__GSTUDIO_SELECTED_PATH__',selected);try{{await navigator.clipboard.writeText(prompt);taskHint.textContent='对应提示词已复制；选择执行工具开始。'}}catch(error){{taskHint.textContent='提示词复制失败；点击执行工具时仍会自动复制。'}}}}));if(search)search.addEventListener('input',()=>{{const q=search.value.trim().toLowerCase();document.querySelectorAll('.inbox-pane.active [data-inbox-search]').forEach(item=>item.style.display=!q||item.dataset.inboxSearch.includes(q)?'':'none')}});</script>"""
    content += '''<script>(()=>{document.querySelectorAll('[data-inbox-tab]').forEach(tab=>tab.addEventListener('click',async()=>{const pane=document.querySelector(`[data-inbox-pane="${tab.dataset.inboxTab}"]`),path=pane?.dataset.inboxPanePath;if(!pane||!path||pane.dataset.loaded==='1')return;pane.innerHTML='<div class="inbox-empty">正在读取目录…</div>';try{const response=await fetch('/api/workspace-inbox/directory?path='+encodeURIComponent(path),{headers:{Accept:'application/json'}}),payload=await response.json();if(!response.ok)throw new Error(payload.error||'读取失败');pane.replaceChildren(...(payload.children||[]).map(item=>makeInboxNode(item,0)));if(!(payload.children||[]).length)pane.innerHTML='<div class="inbox-empty">当前目录为空。</div>';pane.dataset.loaded='1'}catch(error){pane.innerHTML='<div class="inbox-empty">无法读取此目录，请稍后重试。</div>'}}))})();</script>'''
    content += '''<script>(()=>{const root=document.querySelector('.archive-inbox-browser .inbox-content');if(!root)return;const observer=new IntersectionObserver(entries=>entries.forEach(async entry=>{const more=entry.target;if(!entry.isIntersecting||more.dataset.loading==='1')return;more.dataset.loading='1';more.textContent='正在加载下一批…';try{const url='/api/workspace-inbox/directory?path='+encodeURIComponent(more.dataset.inboxLoadMore)+'&offset='+encodeURIComponent(more.dataset.offset||'0'),response=await fetch(url,{headers:{Accept:'application/json'}}),payload=await response.json();if(!response.ok)throw new Error(payload.error||'读取失败');const fragment=document.createDocumentFragment(),depth=Number(more.dataset.depth||0);(payload.children||[]).forEach(item=>fragment.append(makeInboxNode(item,depth)));more.replaceWith(fragment)}catch(error){more.dataset.loading='0';more.textContent='加载失败，继续下拉重试'}}),{root,rootMargin:'160px 0px'});function observe(scope=document){scope.querySelectorAll('[data-inbox-load-more]').forEach(item=>observer.observe(item))}observe();new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1){if(node.matches?.('[data-inbox-load-more]'))observer.observe(node);observe(node)}}))).observe(root,{childList:true,subtree:true})})();</script>'''
    if drive_root:
        drive_root_json = runtime.json.dumps(str(drive_root), ensure_ascii=False)
        workspace_root_json = runtime.json.dumps(str(root), ensure_ascii=False)
